@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ── View transitions ─────────────────────────────────────────── */

/* Directional page slides: forward (grid → detail) moves everything
   left; back (detail → grid) moves everything right. */
@keyframes slide-in-from-right {
  from {
    opacity: 0;
    transform: translateX(4rem);
  }
}

@keyframes slide-out-to-right {
  to {
    opacity: 0;
    transform: translateX(4rem);
  }
}

@keyframes slide-in-from-left {
  from {
    opacity: 0;
    transform: translateX(-4rem);
  }
}

@keyframes slide-out-to-left {
  to {
    opacity: 0;
    transform: translateX(-4rem);
  }
}

::view-transition-new(.page-enter-from-right) {
  animation: slide-in-from-right 300ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

::view-transition-old(.page-exit-to-right) {
  animation: slide-out-to-right 300ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

::view-transition-new(.page-enter-from-left) {
  animation: slide-in-from-left 300ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

::view-transition-old(.page-exit-to-left) {
  animation: slide-out-to-left 300ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* Shared product image: keep the browser's built-in position/size morph,
   just tune its timing. */
::view-transition-group(.product-image-morph) {
  animation-duration: 350ms;
  animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
}

/* Suspense skeleton → content reveal: gentle cross-fade. */
::view-transition-group(.cross-fade),
::view-transition-old(.cross-fade),
::view-transition-new(.cross-fade) {
  animation-duration: 250ms;
  animation-timing-function: ease;
}

/* Respect reduced motion: swap instantly, no morphs or slides, and
   stop the skeleton pulse. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

